package com.example.parcel.domain.parcel;

public final class Parcel {
    public static final double MAX_WEIGHT_KG = 30;

    private final ParcelId id;
    private final double weightKg;

    private Parcel(ParcelId id, double weightKg) {
        this.id = id;
        this.weightKg = weightKg;
    }

    public static Parcel register(ParcelId id, double weightKg) {
        if (weightKg <= 0 || Double.isNaN(weightKg)) {
            throw new IllegalArgumentException("weightKg must be positive");
        }
        if (weightKg > MAX_WEIGHT_KG) {
            throw new ParcelTooHeavyException(id, weightKg);
        }
        return new Parcel(id, weightKg);
    }

    public ParcelId id() { return id; }

    public double weightKg() { return weightKg; }
}
