package com.example.parcel.app.parcel;

import static io.restassured.RestAssured.given;

import io.quarkus.test.junit.QuarkusTest;
import org.junit.jupiter.api.Test;

@QuarkusTest
class ParcelResourceIT {
    private void post(String body, int status) {
        given().contentType("application/json").body(body).when().post("/parcels").then().statusCode(status);
    }

    @Test
    void registersParcel() {
        post("{\"parcelId\":\"p-1\",\"weightKg\":12.5}", 201);
    }

    @Test
    void acceptsExactlyThirtyKilos() {
        post("{\"parcelId\":\"p-2\",\"weightKg\":30}", 201);
    }

    @Test
    void refusesParcelOverThirtyKilosWith422() {
        post("{\"parcelId\":\"p-3\",\"weightKg\":30.5}", 422);
    }

    @Test
    void refusesBlankId() {
        post("{\"parcelId\":\" \",\"weightKg\":5}", 400);
    }
}
