import jakarta.ws.rs.ext.Provider;

@Path("/parcels")
public class ParcelResource {
    public record RegisterParcelRequest(String parcelId, double weightKg) {}

    @Inject
    RegisterParcel registerParcel;

    @POST
    @Consumes(MediaType.APPLICATION_JSON)
    public Response register(RegisterParcelRequest request) {
        if (request == null || request.parcelId() == null) {
            return Response.status(400).build();
        }
        registerParcel.execute(new ParcelId(request.parcelId()), request.weightKg());
        return Response.status(201).build();
    }

    @Provider
    public static class TooHeavyMapper implements ExceptionMapper<ParcelTooHeavyException> {
        @Override
        public Response toResponse(ParcelTooHeavyException e) {
            return Response.status(422).type(MediaType.APPLICATION_JSON)
                    .entity(java.util.Map.of("error", e.getMessage())).build();
        }
    }

    @Provider
    public static class BadInputMapper implements ExceptionMapper<IllegalArgumentException> {
        @Override
        public Response toResponse(IllegalArgumentException e) {
            return Response.status(400).type(MediaType.APPLICATION_JSON)
                    .entity(java.util.Map.of("error", e.getMessage())).build();
        }
    }
}
