package com.example.parcel.application.parcel;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import com.example.parcel.domain.parcel.Parcel;
import com.example.parcel.domain.parcel.ParcelId;
import com.example.parcel.domain.parcel.ParcelTooHeavyException;
import java.util.ArrayList;
import java.util.List;
import org.junit.jupiter.api.Test;

class RegisterParcelTest {
    private final List<Parcel> saved = new ArrayList<>();
    private final RegisterParcel registerParcel = new RegisterParcel(saved::add);

    @Test
    void savesAcceptedParcel() {
        registerParcel.execute(new ParcelId("p-1"), 12.5);
        assertThat(saved).hasSize(1);
    }

    @Test
    void savesNothingWhenTooHeavy() {
        assertThatThrownBy(() -> registerParcel.execute(new ParcelId("p-1"), 31))
                .isInstanceOf(ParcelTooHeavyException.class);
        assertThat(saved).isEmpty();
    }
}
